parameters.jsCode:
const inbound = $('Workflow Input (from WF01)').item.json;
const cfg = $('Load Business Config').item.json;
const ctx = $('Load Conversation Context').item.json;
const cls = ($('Classify Intent').item.json.output) || {};
const data = $('Retrieve Verified Data').item.json;
const llm = ($('Generate Structured Reply').item.json.output) || {};

const lang = cls.language || cfg.default_language || 'bn';
const T = {
  handover: {
    bn: 'আপনার বার্তার জন্য ধন্যবাদ। বিষয়টি আমাদের টিমকে জানানো হয়েছে, একজন প্রতিনিধি শীঘ্রই আপনার সাথে যোগাযোগ করবেন।',
    en: 'Thank you for your message. I have passed this to our team and a representative will contact you shortly.'
  },
  clarify: {
    bn: 'দুঃখিত, আমি পণ্যটি নিশ্চিতভাবে খুঁজে পাইনি। অনুগ্রহ করে পণ্যের নাম বা কোডটি জানাবেন?',
    en: 'Sorry, I could not find that product. Could you share the product name or code?'
  }
};
const pick = function (o) { return lang === 'bn' ? o.bn : o.en; };

const bn = '০১২৩৪৫৬৭৮৯';
const normDigits = function (s) {
  return String(s || '').replace(/[০-৯]/g, function (d) { return String(bn.indexOf(d)); });
};
const numsIn = function (s) {
  const m = normDigits(s).match(/\d[\d,]*/g) || [];
  return m.map(function (x) { return x.replace(/,/g, ''); }).filter(function (x) { return x.length >= 3; });
};

const products = data.products || [];
const allowed = new Set();
products.forEach(function (p) {
  allowed.add(String(Math.round(Number(p.price_bdt))));
  if (p.size_ml) allowed.add(String(p.size_ml));
  numsIn(p.sku).forEach(function (n) { allowed.add(n); });
  numsIn(p.description).forEach(function (n) { allowed.add(n); });
  numsIn(p.scent_notes).forEach(function (n) { allowed.add(n); });
});
(data.orders || []).forEach(function (o) {
  allowed.add(String(Math.round(Number(o.total_bdt))));
  numsIn(o.order_id).forEach(function (n) { allowed.add(n); });
});
(data.settings || []).forEach(function (s) { numsIn(s.setting_value).forEach(function (n) { allowed.add(n); }); });
(data.faqs || []).forEach(function (f) { numsIn(f.answer).forEach(function (n) { allowed.add(n); }); });
numsIn(inbound.message_text).forEach(function (n) { allowed.add(n); });
allowed.add(String(new Date().getFullYear()));

const reasons = [];
const intent = llm.intent || cls.intent || 'unknown';
const confidence = Number(llm.confidence != null ? llm.confidence : (cls.confidence != null ? cls.confidence : 0));
const escalate = ['complaint', 'human_request'];
let needsHuman = !!llm.needs_human || escalate.includes(intent) || escalate.includes(cls.intent) || confidence < 0.6;
if (needsHuman) reasons.push('escalation intent, model flag or low confidence');

let reply = String(llm.reply || '').trim();
if (!reply) { needsHuman = true; reasons.push('empty reply'); }

const factual = ['product_price', 'product_details', 'availability'];
if (!needsHuman && factual.includes(intent) && products.length === 0) {
  reply = pick(T.clarify);
  reasons.push('no verified product match');
}
if (!needsHuman) {
  const bad = numsIn(reply).filter(function (n) { return !allowed.has(n); });
  if (bad.length > 0) { needsHuman = true; reasons.push('reply contained unverified number'); }
}

let action = 'reply';
if (needsHuman) {
  action = 'handover';
  reply = pick(T.handover);
} else if (intent === 'order_start' || llm.required_action === 'start_order') {
  action = 'start_order';
}

const et = Number(inbound.event_time || 0);
const withinWindow = !et || (Date.now() - et) < 23 * 3600 * 1000;
let blockReason = '';
if (!cfg.graph_api_version) blockReason = 'META_GRAPH_API_VERSION not configured';
else if (inbound.platform === 'instagram' && !cfg.ig_user_id) blockReason = 'IG_USER_ID not configured';
else if (ctx.consent_status === 'revoked') blockReason = 'customer revoked consent';
else if (!withinWindow) blockReason = 'outside 24h messaging window';

return { json: {
  platform: inbound.platform,
  page_id: inbound.page_id,
  sender_id: inbound.sender_id,
  event_time: inbound.event_time,
  webhook_event_id: inbound.webhook_event_id || 0,
  customer_id: ctx.customer_id,
  conversation_id: ctx.conversation_id,
  message_id: ctx.message_id,
  message_text: inbound.message_text || '',
  message_excerpt: String(inbound.message_text || '').slice(0, 120),
  intent: intent,
  confidence: confidence,
  product_id: llm.product_id == null ? null : llm.product_id,
  required_action: llm.required_action || 'none',
  missing_information: llm.missing_information || [],
  needs_human: needsHuman,
  action: action,
  final_reply: reply,
  reasons: reasons,
  can_send: blockReason === '',
  block_reason: blockReason
} };

